pipeline_runner:
$ErrorActionPreference = 'Stop'
$engineExe = Join-Path (Get-Location) 'target/release/examples/engine_perf.exe'
$outputDir = Join-Path (Get-Location) 'target/engine-perf'
$runs = @(
    @{ Name='pipeline-1k-name'; Records=1000; Files=1; Samples=7; Updates=100; Batches='1'; Field='name' },
    @{ Name='pipeline-10k-name'; Records=10000; Files=10; Samples=5; Updates=5; Batches='1,10,100,1000'; Field='name' },
    @{ Name='pipeline-100k-name'; Records=100000; Files=100; Samples=3; Updates=3; Batches='1,1000'; Field='name' },
    @{ Name='pipeline-10k-value'; Records=10000; Files=10; Samples=3; Updates=3; Batches='1'; Field='value' }
)
foreach ($run in $runs) {
    $env:ENGINE_MODE = 'pipeline'
    $env:ENGINE_RECORDS = [string]$run.Records
    $env:ENGINE_FILES = [string]$run.Files
    $env:ENGINE_SAMPLES = [string]$run.Samples
    $env:ENGINE_UPDATE_SAMPLES = [string]$run.Updates
    $env:ENGINE_BATCHES = $run.Batches
    $env:ENGINE_FIELD = $run.Field
    Write-Output "Starting $($run.Name)"
    $stdoutPath = Join-Path $outputDir "$($run.Name).jsonl"
    $stderrPath = Join-Path $outputDir "$($run.Name).stderr.txt"
    $watch = [System.Diagnostics.Stopwatch]::StartNew()
    $process = Start-Process -FilePath $engineExe -PassThru -WindowStyle Hidden -RedirectStandardOutput $stdoutPath -RedirectStandardError $stderrPath
    $peakBytes = 0L
    while (-not $process.HasExited) {
        $process.Refresh()
        $peakBytes = [Math]::Max($peakBytes, $process.PeakWorkingSet64)
        $null = $process.WaitForExit(500)
    }
    $process.WaitForExit()
    $watch.Stop()
    [ordered]@{
        name=$run.Name; exit_code=$process.ExitCode; peak_working_set_bytes=$peakBytes
        process_elapsed_seconds=$watch.Elapsed.TotalSeconds; config=$run
    } | ConvertTo-Json -Depth 4 | Set-Content (Join-Path $outputDir "$($run.Name).process.json")
    Get-Content $stdoutPath | ForEach-Object {
        $row = $_ | ConvertFrom-Json
        if ($null -ne $row.median_ms) {
            Write-Output "$($row.metric): $([Math]::Round($row.median_ms,3)) ms"
        }
    }
    if ($process.ExitCode -ne 0) {
        Get-Content $stderrPath
        exit $process.ExitCode
    }
    Write-Output "Completed $($run.Name); peak working set $([Math]::Round($peakBytes / 1MB, 1)) MiB"
}
